{
  "description": "The creature is a quadrupedal mammal shown in right-facing profile with the overall body, fur, head, limbs and proportions of a brown bear but with beetle features integrated into its back and forehead. It has thick shaggy brown fur with lighter tan on the muzzle and underbelly, four sturdy legs ending in clawed paws, a small rounded tail at the rear, and two small rounded ears on top of the head. A large glossy dark brown hardened shell covers the entire dorsal back from the shoulders to the rump, and a single long curved glossy dark brown horn projects upward and backward from the center of the forehead. A row of small oval dark openings is visible in the fur along the side of the torso just below the edge of the shell.",
  "parts": [
    {
      "part": "head",
      "looks_like": "bear-like head with brown fur, lighter tan fur on the muzzle and around the mouth, a large dark brown-black nose at the tip, small brown eyes, and fine whiskers on the muzzle",
      "where": "at the front end of the body, facing to the right in profile"
    },
    {
      "part": "horns",
      "looks_like": "single large glossy dark brown curved horn with a smooth surface, a small pointed tooth-like projection on the inner curve and fine serrations along the lower inner edge, tapering to a sharp tip",
      "where": "rising from the center of the forehead on top of the head, curving upward and backward"
    },
    {
      "part": "ears",
      "looks_like": "two small rounded ears covered in dense fluffy brown fur",
      "where": "on top of the head behind the horn, one slightly behind the other in profile view"
    },
    {
      "part": "legs",
      "looks_like": "four thick muscular legs covered in long shaggy dark brown fur, with lighter brown fur on the inner and lower torso between them",
      "where": "two forelegs under the chest and shoulder area and two hind legs under the hip and rump, supporting the body"
    },
    {
      "part": "feet",
      "looks_like": "four large broad paws with dark curved claws protruding from the toes, fur covering the top and sides",
      "where": "at the bottom ends of each leg in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "small short rounded tuft of brown fur",
      "where": "at the rear of the body above the hind legs"
    },
    {
      "part": "shell",
      "looks_like": "glossy dark brown hardened beetle-like carapace with longitudinal ridges on the rear section and a cracked, veined texture with light reflections",
      "where": "covering the dorsal back from just behind the neck/shoulders to the rump, sitting on top of the fur"
    },
    {
      "part": "plates",
      "looks_like": "two distinct shiny plates: a larger elongated oval plate with parallel ridges covering the mid-back to rump, and a smaller shield-shaped plate with irregular crack lines covering the shoulder area, separated by a narrow gap",
      "where": "on the back, the smaller plate over the shoulders and the larger plate over the back and hindquarters"
    },
    {
      "part": "markings",
      "looks_like": "rows of small oval dark holes with light rims, resembling spiracles, set in the fur",
      "where": "along the side of the torso just below the lower edge of the shell, with about six holes on the mid-body and four smaller holes on the shoulder area"
    }
  ],
  "attached_objects": [],
  "animals": [
    "bear",
    "beetle"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
